import sys

class Node:
    __slots__ = ('key', 'prev', 'next')
    def __init__(self, key):
        self.key = key
        self.prev = None
        self.next = None

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    commands = input[1:n+1]

    head = None
    tail = None

    for cmd in commands:
        parts = cmd.split()
        if parts[0] == 'insert':
            x = int(parts[1])
            new_node = Node(x)
            if head is None:
                head = tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif parts[0] == 'delete':
            x = int(parts[1])
            current = head
            while current is not None:
                if current.key == x:
                    if current == head:
                        if current == tail:
                            head = tail = None
                        else:
                            head = current.next
                            head.prev = None
                    elif current == tail:
                        tail = current.prev
                        tail.next = None
                    else:
                        prev_node = current.prev
                        next_node = current.next
                        prev_node.next = next_node
                        next_node.prev = prev_node
                    break
                current = current.next
        elif parts[0] == 'deleteFirst':
            if head is not None:
                if head == tail:
                    head = tail = None
                else:
                    new_head = head.next
                    new_head.prev = None
                    head = new_head
        elif parts[0] == 'deleteLast':
            if tail is not None:
                if head == tail:
                    head = tail = None
                else:
                    new_tail = tail.prev
                    new_tail.next = None
                    tail = new_tail

    result = []
    current = head
    while current is not None:
        result.append(str(current.key))
        current = current.next
    print(' '.join(result))

